  "shell.sides.previewHint": "Establezca el comportamiento de apertura de archivos por separado para los enlaces de conversación y el árbol de archivos o la lista de cambios. Reemplazar vista previa: el siguiente archivo reemplaza la pestaña en cursiva. Ctrl + clic (⌘ + clic en macOS) o clic central abre una pestaña persistente en segundo plano; hacer doble clic en una pestaña también la mantiene abierta. El mismo archivo reutiliza su pestaña existente",
