  "desk.setting": "Varias ventanas",
  "desk.settingHint": "Mover una conversación a su propia ventana, por ejemplo en otra pantalla (conversación ⋯ → Mover a una nueva ventana); cuando está desactivado, esos elementos del menú desaparecen y las ventanas recordadas no se vuelven a abrir al inicio. Cada ventana abierta sigue actualizando las respuestas en vivo. Varias ventanas en pantalla utilizan notablemente más CPU y pueden hacer que la escritura sea lenta. Minimiza o cierra las ventanas que no estés usando.",
